// LabFlow: share of opening hours already booked (0..1).
const OPEN = 7 * 60;
const CLOSE = 21 * 60;

export function usageRate(bookings: any): number {
  let rate = 0;
  for (const b of bookings) rate += b.minute / (CLOSE - OPEN);
  return rate;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { usageRate } from '../src/usage.ts';

test('420 + 420 minutes fill one day', () => assert.equal(usageRate([{ minutes: 420 }, { minutes: 420 }]), 1));
test('no bookings is 0', () => assert.equal(usageRate([]), 0));

import { usageRate } from '../src/usage.ts';

usageRate([{ minute: 60 }]); // expect TS2561
usageRate(120); // expect TS2345

