// LabFlow BR-04: a slot is on a 30-minute grid, inside 07:00–21:00, at most 4 hours.
export function parseTime(text) {
  const m = /^([0-9]{2}):([0-9]{2})$/.exec(text);
  if (!m) throw new TypeError('Invalid time "' + text + '", expected HH:MM');
  return Number(m[1]) * 60 + Number(m[2]);
}

export function checkSlot(start, end) {
  const s = parseTime(start);
  const e = parseTime(end);
  if (s % 30 !== 0 || e % 30 !== 0) return 'OFF_GRID';
  if (e <= s) return 'END_BEFORE_START';
  if (s < 420 || e > 1260) return 'OUTSIDE_HOURS';
  if (e - s > 240) return 'TOO_LONG';
  return 'OK';
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { checkSlot, parseTime } from '../src/slot.ts';

test('07:30 is minute 450', () => assert.equal(parseTime('07:30'), 450));
test('08:00-10:00 is OK', () => assert.equal(checkSlot('08:00', '10:00'), 'OK'));
test('08:15 is off the grid', () => assert.equal(checkSlot('08:15', '09:00'), 'OFF_GRID'));

