// LabFlow BR-06: students need approval above 30 seats; lecturers and admins never do.
export function needsApproval({ seats, role }: { seats: number; role: string }): boolean {
  if (!Number.isInteger(seats) || seats < 1) throw new RangeError('seats must be a positive integer, got ' + seats);
  if (role === 'LECTURER' || role === 'ADMIN') return false;
  return seats > 30;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { needsApproval } from '../src/approval.ts';

test('31 student seats need approval', () => assert.equal(needsApproval({ seats: 31, role: 'STUDENT' }), true));
test('admins never wait', () => assert.equal(needsApproval({ seats: 200, role: 'ADMIN' }), false));
test('a lecturer with 31 seats does not wait', () => assert.equal(needsApproval({ seats: 31, role: 'LECTURER' }), false));

import { needsApproval } from '../src/approval.ts';

needsApproval({ seats: 31, role: 'lecturer' }); // expect TS2820
needsApproval({ seats: 31, role: 'GUEST' }); // expect TS2322

