// LabFlow: build a booking. Untyped JavaScript, renamed to .ts.
export function createBooking({ lab, seats, role, start, end }) {
  const wait = role === 'STUDENT' && seats > 30;
  return { lab, start, end, seats, status: wait ? 'PENDING' : 'CONFIRMED' };
}

