// LabFlow: build a booking, now with the input and the result written down as types.
export type Role = 'STUDENT' | 'LECTURER' | 'ADMIN';
export type BookingInput = { lab: string; seats: number; role: Role; start: string; end: string };
export type Booking = { lab: string; start: string; end: string; seats: number; status: 'PENDING' | 'CONFIRMED' };

export function createBooking({ lab, seats, role, start, end }: BookingInput): Booking {
  const wait = role === 'STUDENT' && seats > 30;
  return { lab, start, end, seats, status: wait ? 'PENDING' : 'CONFIRMED' };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createBooking } from '../src/booking.ts';

test('31 student seats wait', () => assert.equal(createBooking({ lab: 'BE-201', seats: 31, role: 'STUDENT', start: '08:00', end: '10:00' }).status, 'PENDING'));
test('a lecturer is confirmed', () => assert.equal(createBooking({ lab: 'BE-201', seats: 31, role: 'LECTURER', start: '08:00', end: '10:00' }).status, 'CONFIRMED'));

import { createBooking } from '../src/booking.ts';

